<?php
namespace App\Http\Controllers;
use Illuminate\Routing\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Hash,Storage};
use Illuminate\Validation\Rules\Password;
use App\Services\{Registration,Support,Geography,Municipalities,Fleet};
class PublicCourierController extends Controller {
 public function form(){return view('guest-tools',['title'=>'Register logistics rider or driver','forms'=>[['label'=>'Rider / driver registration','action'=>'/register/courier','fields'=>['courier_type:select:rider,driver','first_name','last_name','email:email','phone','date_of_birth:date','region','province','city','barangay','street','postal_code','vehicle:select:motorcycle,tricycle,4-wheel truck,6-wheel truck,8-wheel truck,10-wheel truck','license_number','license_expires_at:date','plate_number','id_document:file','permit_document:file','password:password','password_confirmation:password','terms:checkbox']]]]);}
 public function register(Request $r){$r->merge(['email'=>mb_strtolower(trim((string)$r->email)),'phone'=>Registration::normalizePhone((string)$r->phone),'plate_number'=>strtoupper(trim((string)$r->plate_number)),'license_number'=>strtoupper(trim((string)$r->license_number))]);$name=['required','string','min:2','max:50',"regex:/^[\p{L}\p{M} .'-]+$/u"];$file='required|file|mimes:jpg,jpeg,png,pdf|extensions:jpg,jpeg,png,pdf|max:5120';
 $v=$r->validate(['courier_type'=>'required|in:rider,driver','first_name'=>$name,'last_name'=>$name,'email'=>'required|email|unique:users,email','phone'=>['required','regex:/^09[0-9]{9}$/','unique:users,phone_normalized'],'date_of_birth'=>'required|date|before_or_equal:'.now()->subYears(18)->toDateString(),'region'=>'required|string|max:120','province'=>'required|string|max:120','city'=>'required|string|max:120','barangay'=>'required|string|max:120','street'=>'required|string|max:200','postal_code'=>['required','regex:/^[0-9]{4}$/'],'vehicle'=>'required|string|max:120','license_number'=>['required','regex:/^[A-Z][0-9]{2}-[0-9]{2}-[0-9]{6}$/','unique:users,license_number'],'license_expires_at'=>'required|date|after_or_equal:today','plate_number'=>'required|string|max:20|unique:users,plate_number','id_document'=>$file,'permit_document'=>$file,'password'=>['required','confirmed',Password::min(8)->mixedCase()->numbers()->symbols()],'terms'=>'accepted']);
 Geography::validate($v);Fleet::validate($v['courier_type'],$v['vehicle']);$center=Municipalities::centerFor((object)$v);if(!$center)Support::fail('city','Your municipality needs an approved sorting center before you can register as its rider or driver.');$paths=[];
 try{$id=DB::transaction(function()use($r,$v,$center,&$paths){$owner=DB::table('users')->where('id',$center->user_id)->lockForUpdate()->first();if(!$owner||!$owner->active||$owner->account_status!=='active'||$owner->approval_status!=='approved')Support::fail('city','This sorting center is unavailable.');$id=\App\Services\PendingRegistration::user(['name'=>$v['first_name'].' '.$v['last_name'],'first_name'=>$v['first_name'],'last_name'=>$v['last_name'],'email'=>$v['email'],'phone'=>$v['phone'],'phone_normalized'=>$v['phone'],'date_of_birth'=>$v['date_of_birth'],'password'=>Hash::make($v['password']),'role'=>'rider','courier_type'=>$v['courier_type'],'company_id'=>$center->user_id,'vehicle'=>$v['vehicle'],'license_number'=>$v['license_number'],'license_expires_at'=>$v['license_expires_at'],'plate_number'=>$v['plate_number'],'region'=>$v['region'],'approval_status'=>'unverified','verification_required'=>1,'active'=>1,'online'=>0,'terms_accepted_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);\App\Services\PendingRegistration::related('addresses',['user_id'=>$id,'recipient'=>$v['first_name'].' '.$v['last_name'],'phone'=>$v['phone'],'street'=>$v['street'],'barangay'=>$v['barangay'],'city'=>$v['city'],'province'=>$v['province'],'postal_code'=>$v['postal_code'],'is_default'=>1,'created_at'=>now(),'updated_at'=>now()]);foreach(['id_document','permit_document'] as $field){$path=$r->file($field)->store('documents','local');$paths[]=$path;\App\Services\PendingRegistration::related('registration_documents',['user_id'=>$id,'kind'=>$field,'path'=>$path,'created_at'=>now(),'updated_at'=>now()]);}Registration::issueOtp($id,$v['email']);return $id;});}catch(\Throwable $e){foreach($paths as $p)Storage::disk('local')->delete($p);if($e instanceof \Illuminate\Database\UniqueConstraintViolationException)Support::fail('email','An account with these email, phone, license or plate details already exists.');throw $e;}
 $r->session()->regenerate();$r->session()->put('company_pending_registration_id',$id);return redirect('/company/verify')->with('success','Check your email for the verification code.');
 }
}
